#pragma once
static const char wirelessPage[]=R"HTML(<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>COGS robot</title><style>body{font:17px system-ui;max-width:760px;margin:30px auto;padding:0 20px;background:#f5f5f0;color:#152b31}button,input{font:inherit;padding:12px;margin:6px 0}button{cursor:pointer}input{width:95%}pre{white-space:pre-wrap;background:white;padding:16px}small{display:block}#start{background:#174e41;color:white;border:0}</style><h1>COGS robot</h1><p>Wireless setup · standalone line → maze</p><p>The robot runs without this page. During motion, Wi-Fi controls and status pause. Press the physical button to stop before picking up the robot.</p><button id="refresh">Refresh status</button><pre id="status" aria-live="polite">Loading…</pre><button id="start">Start a fresh line-to-maze run</button><small>Place the robot on the line first. Starting clears the previous route map.</small><pre id="result" aria-live="polite"></pre><script>
const result=document.querySelector('#result');
async function refresh(){try{document.querySelector('#status').textContent=await(await fetch('/status',{cache:'no-store'})).text();}catch(e){result.textContent='Robot unavailable. During a run, use the physical button to stop.'}}
async function send(cmd){result.textContent='Sending…';try{let r=await fetch('/command',{method:'POST',headers:{'X-Robot-Control':'1','Content-Type':'text/plain'},body:cmd});result.textContent=await r.text();if(cmd!=='RUN START')await refresh()}catch(e){result.textContent='No response. Do not assume the command failed. Use the physical button to stop.'}}
document.querySelector('#refresh').onclick=refresh;document.querySelector('#start').onclick=()=>{if(confirm('Start moving now? This clears the previous route map.'))send('RUN START')};refresh();
</script></html>)HTML";
